        None => Ok(None),
        Some(Value::String(token)) if token.is_empty() => Ok(None),
        Some(Value::String(token)) if seen.insert(token.clone()) => Ok(Some(token.clone())),
        _ => Err("list event `*`: invalid or repeated nextPageToken".into()),
