async fn build_request_from_store_with_context(
    state: &AppState,
    mode: PlanningModeBody,
    repair_context: Option<RepairContextBody>,
    excluded_task_ids: &[String],
    explicit_horizon: Option<&PlanningHorizonBody>,
) -> Result<StorePlanningRequest> {
    let now = timestamp_seconds(&state.planning_now().to_string())?;
    // Dynamic packing begins on a whole minute, never at the second of the
    // request. Anchored at the exact instant, two Plans made seconds apart had
    // different Dynamic windows, and every re-plan rewrote every Dynamic event
    // on the calendar. Rounded UP: rounding down would place work in the past.
    // The horizon's end is derived from the rounded start, so its span is still
    // exactly the configured number of seconds.
    let anchor = next_whole_minute(now);
    let pre_repair_horizon = resolve_time_window(state, explicit_horizon, anchor).await?;
    let routine_context =
        super::routine_service::materialize(state, &pre_repair_horizon, now).await?;
    let pool = state.inner().store.pool();
    let tasks = queries::query_active_tasks(pool)
        .await
        .map_err(AppError::from)?;

    let static_windows = stored_static_windows(pool).await?;
    let excluded: HashSet<_> = excluded_task_ids.iter().cloned().collect();
    let task_rows = tasks
        .into_iter()
        .filter(|record| !excluded.contains(&record.id))
        .map(|record| {
            let payload = serde_json::from_str::<Value>(&record.payload_json)
                .map_err(|e| AppError::Internal(format!("failed to deserialize task: {e}")))?;
            Ok(TaskRow {
                id: record.id,
                payload,
            })
        })
        .collect::<Result<Vec<_>>>()?;

    let TaskPreconditionPartition {
        eligible: task_rows,
        blocked: blocked_tasks,
        invalid: invalid_tasks,
    } = partition_tasks_by_preconditions(pool, task_rows, crate::instance_mode::MVP_INSTANCE_MODE)
        .await?;

    // Resolve H using the existing fallback before applying participation rules.
    let mut task_bodies = task_rows
        .iter()
        .map(|task| TaskSpecBody {
            mandatory: false,
            value: 1.0,
            id: task.id.clone(),
            duration: duration_seconds(&task.payload),
            duration_estimate: None,
            correlation_groups: Vec::new(),
            depends_on: Vec::new(),
            window: None,
            static_anchor: None,
        })
        .collect::<Vec<_>>();

    let mut time_window = pre_repair_horizon.clone();
    if repair_context.is_some() {
        time_window.start = time_window.start.max(now);
        if let Some(prior_plan) = latest_admitted_plan(state).await? {
            if let Some(max_frozen_end) = prior_plan
                .steps
                .iter()
                .filter(|step| excluded.contains(&step.task_id))
                .map(|step| step.end)
                .max()
            {
                time_window.start = time_window.start.max(max_frozen_end);
            }
        }
        if time_window.end <= time_window.start {
            let remaining_duration = task_bodies
                .iter()
                .map(|task| task.duration)
