        .iter()
        .filter(|t| t.payload.get("occurrence").is_some_and(|v| !v.is_null()))
        .map(|t| t.id.clone())
        .collect();
    let mut diagnostics = routine_context.diagnostics;
    let mut non_capacity_tasks = Vec::new();
    let mut absent_static_windows = HashMap::new();
    task_bodies.clear();
